template<int DIMENSION_NO, typename TGeometry>
struct VectorND {
    TGeometry& operator[](size_t index) { return data[index]; }
    const TGeometry& operator[](size_t index) const { return data[index]; }
    TGeometry data[DIMENSION_NO];
};

template<int DIMENSION_NO, typename TGeometry>
struct BoundingBoxND {
    VectorND<DIMENSION_NO, TGeometry> Min;
    VectorND<DIMENSION_NO, TGeometry> Max;
};

using Point3D = VectorND<3, double>;
using BoundingBox3D = BoundingBoxND<3, double>;

bool IsPointInBox(const Point3D& point, const BoundingBox3D& box) {
    return (point[0] >= box.Min[0] && point[0] <= box.Max[0]) &&
           (point[1] >= box.Min[1] && point[1] <= box.Max[1]) &&
           (point[2] >= box.Min[2] && point[2] <= box.Max[2]);
}

// Test cases
int main() {
    BoundingBox3D box = {{{0.0, 0.0, 0.0}}, {{1.0, 1.0, 1.0}}};
    Point3D inside = {{0.5, 0.5, 0.5}};
    Point3D outside = {{1.5, 0.5, 0.5}};
    Point3D on_boundary = {{1.0, 1.0, 1.0}};

    bool test1 = IsPointInBox(inside, box); // true
    bool test2 = IsPointInBox(outside, box); // false
    bool test3 = IsPointInBox(on_boundary, box); // true

    return (test1 && !test2 && test3) ? 0 : 1;
}

